<?php
require_once __DIR__.'/../includes/bootstrap.php';
require_role('information_officer');
$user=current_user();$uid=(int)($user['id']??$user['user_id']??0);$db=Database::getConnection();$profileLabel=trim((string)($user['full_name']??$user['name']??$user['username']??'Information Officer'));$profileInitials=strtoupper(substr(preg_replace('/[^A-Za-z0-9]/','',$profileLabel)?:'IO',0,2));
function ioe($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function ioHas($db,$t){$s=$db->prepare('SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?');if(!$s)return false;$s->bind_param('s',$t);$s->execute();$ok=(bool)$s->get_result()->fetch_row();$s->close();return $ok;}
function ioLog($db,$uid,$action,$type,$id){if(!ioHas($db,'io_audit_events'))return;$s=$db->prepare('INSERT INTO io_audit_events(actor_user_id,action,entity_type,entity_id) VALUES(?,?,?,?)');if($s){$s->bind_param('isss',$uid,$action,$type,$id);$s->execute();$s->close();}}
$config=[
'requests'=>['Data-subject requests','Register and track access, correction, objection, restriction and deletion-assessment requests.','io_data_subject_requests',['id','request_type','status','priority','received_at','due_date','subject_reference']],
'incidents'=>['Privacy incident register','Record, triage and monitor suspected or confirmed privacy incidents.','io_privacy_incidents',['id','incident_type','severity','summary','status','reported_at']],
'access_reviews'=>['Access reviews','Plan periodic reviews of privileged and role-scoped access.','io_access_reviews',['id','review_name','status','due_date','reviewed_by','completed_at']],
'retention'=>['Retention schedule','Track review dates and documented retention decisions.','io_retention_reviews',['id','record_category','retention_basis','retention_period','due_date','legal_hold','proposed_action','status']],
'audit'=>['Privacy audit log','Review portal activity recorded by this module.','io_audit_events',['id','actor_user_id','action','entity_type','entity_id','purpose','outcome','created_at']],
'processing'=>['Processing activities register','Maintain an inventory of personal-information processing purposes, categories, lawful grounds, recipients and safeguards.','io_processing_activities',['id','activity_name','business_owner','purpose','personal_information_categories','data_subject_categories','lawful_basis','recipients','security_safeguards','cross_border_transfer','status','review_due_date']],
'operators'=>['Operator register','Maintain oversight of third-party operators and documented safeguards.','io_operator_register',['id','operator_name','service_description','information_categories','agreement_reference','security_measures','incident_contact','review_due_date','status']]
];
$key=$_GET['module']??'requests';if(!isset($config[$key]))$key='requests';[$title,$desc,$table,$cols]=$config[$key];$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!ioHas($db,$table))$message='Run database/information_officer_portal.sql first.';
 elseif($key==='requests'){$type=$_POST['request_type']??'other';$valid=['access','correction','objection','deletion_assessment','restriction','consent_withdrawal','other'];if(!in_array($type,$valid,true))$type='other';$p=$_POST['priority']??'normal';if(!in_array($p,['low','normal','high','urgent'],true))$p='normal';$d=trim($_POST['description']??'');$ref=trim($_POST['subject_reference']??'');$due=trim($_POST['due_date']??'');if(!$d)$message='Request summary is required.';else{$s=$db->prepare("INSERT INTO io_data_subject_requests(request_type,subject_reference,description,priority,due_date,created_by) VALUES(?,?,?,?,NULLIF(?,''),?)");$s->bind_param('sssssi',$type,$ref,$d,$p,$due,$uid);if($s->execute()){ioLog($db,$uid,'create_request','request',(string)$s->insert_id);$message='Request recorded.';}else$message='Could not save the request.';$s->close();}}
 elseif($key==='incidents'){$type=$_POST['incident_type']??'other';$valid=['unauthorised_access','data_loss','wrong_recipient','disclosure','device_loss','malware','availability','other'];if(!in_array($type,$valid,true))$type='other';$sev=$_POST['severity']??'medium';if(!in_array($sev,['low','medium','high','critical'],true))$sev='medium';$sum=trim($_POST['summary']??'');$d=trim($_POST['details']??'');if(!$sum||!$d)$message='Summary and details are required.';else{$s=$db->prepare('INSERT INTO io_privacy_incidents(incident_type,severity,summary,details,created_by) VALUES(?,?,?,?,?)');$s->bind_param('ssssi',$type,$sev,$sum,$d,$uid);if($s->execute()){ioLog($db,$uid,'report_incident','incident',(string)$s->insert_id);$message='Incident recorded. Follow the approved incident-response procedure.';}else$message='Could not save incident.';$s->close();}}
 elseif($key==='access_reviews'){$n=trim($_POST['review_name']??'');$sc=trim($_POST['scope_description']??'');$due=trim($_POST['due_date']??'');if(!$n||!$sc)$message='Review name and scope are required.';else{$s=$db->prepare("INSERT INTO io_access_reviews(review_name,scope_description,due_date,created_by) VALUES(?,?,NULLIF(?,''),?)");$s->bind_param('sssi',$n,$sc,$due,$uid);if($s->execute()){ioLog($db,$uid,'create_access_review','access_review',(string)$s->insert_id);$message='Access review created.';}else$message='Could not save review.';$s->close();}}
 elseif($key==='retention'){$n=trim($_POST['record_category']??'');$b=trim($_POST['retention_basis']??'');$p=trim($_POST['retention_period']??'');$due=trim($_POST['due_date']??'');if(!$n||!$b||!$p)$message='Category, basis and period are required.';else{$s=$db->prepare("INSERT INTO io_retention_reviews(record_category,retention_basis,retention_period,due_date,created_by) VALUES(?,?,?,NULLIF(?,''),?)");$s->bind_param('ssssi',$n,$b,$p,$due,$uid);if($s->execute()){ioLog($db,$uid,'create_retention_review','retention',(string)$s->insert_id);$message='Retention review added.';}else$message='Could not save review.';$s->close();}}
}

 elseif($key==='processing'){
  $name=trim($_POST['activity_name']??'');$owner=trim($_POST['business_owner']??'');$purpose=trim($_POST['purpose']??'');
  $pic=trim($_POST['personal_information_categories']??'');$dsc=trim($_POST['data_subject_categories']??'');
  $basis=trim($_POST['lawful_basis']??'');$rec=trim($_POST['recipients']??'');$safe=trim($_POST['security_safeguards']??'');
  $cross=($_POST['cross_border_transfer']??'no')==='yes'?'yes':'no';$due=trim($_POST['review_due_date']??'');
  if(!$name||!$owner||!$purpose||!$pic||!$dsc||!$basis||!$safe)$message='Complete all required processing inventory fields.';
  else{$s=$db->prepare("INSERT INTO io_processing_activities(activity_name,business_owner,purpose,personal_information_categories,data_subject_categories,lawful_basis,recipients,security_safeguards,cross_border_transfer,review_due_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,NULLIF(?,''),?)");
   $s->bind_param('ssssssssssi',$name,$owner,$purpose,$pic,$dsc,$basis,$rec,$safe,$cross,$due,$uid);
   if($s->execute()){ioLog($db,$uid,'create_processing_activity','processing_activity',(string)$s->insert_id);$message='Processing activity recorded.';}else $message='Could not save processing activity.';$s->close();}
 }
 elseif($key==='operators'){
  $name=trim($_POST['operator_name']??'');$desc=trim($_POST['service_description']??'');$cats=trim($_POST['information_categories']??'');
  $agreement=trim($_POST['agreement_reference']??'');$measures=trim($_POST['security_measures']??'');$contact=trim($_POST['incident_contact']??'');$due=trim($_POST['review_due_date']??'');
  if(!$name||!$desc||!$measures)$message='Operator name, service description and security measures are required.';
  else{$s=$db->prepare("INSERT INTO io_operator_register(operator_name,service_description,information_categories,agreement_reference,security_measures,incident_contact,review_due_date,created_by) VALUES(?,?,?,?,?,?,NULLIF(?,''),?)");
   $s->bind_param('sssssssi',$name,$desc,$cats,$agreement,$measures,$contact,$due,$uid);
   if($s->execute()){ioLog($db,$uid,'create_operator','operator',(string)$s->insert_id);$message='Operator recorded.';}else $message='Could not save operator.';$s->close();}
 }

$content='';if($key==='requests')$content.='<section class="card"><h2>Register request</h2><form method="post"><div class="grid"><div><label>Request type</label><select name="request_type"><option>access</option><option>correction</option><option>objection</option><option>deletion_assessment</option><option>restriction</option><option>consent_withdrawal</option><option>other</option></select></div><div><label>Priority</label><select name="priority"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></div><div><label>Internal subject reference</label><input name="subject_reference" maxlength="100"></div><div><label>Due date</label><input type="date" name="due_date"></div></div><label>Request summary</label><textarea name="description" required maxlength="5000"></textarea><p><button class="btn primary">Record request</button></p></form></section>';
if($key==='incidents')$content.='<section class="card"><h2>Report incident</h2><p class="muted">This form does not automatically notify regulators or affected people.</p><form method="post"><div class="grid"><div><label>Incident type</label><select name="incident_type"><option>other</option><option>unauthorised_access</option><option>data_loss</option><option>wrong_recipient</option><option>disclosure</option><option>device_loss</option><option>malware</option><option>availability</option></select></div><div><label>Severity</label><select name="severity"><option>medium</option><option>low</option><option>high</option><option>critical</option></select></div></div><label>Summary</label><input name="summary" required maxlength="255"><label>Details</label><textarea name="details" required maxlength="8000"></textarea><p><button class="btn primary">Record incident</button></p></form></section>';
if($key==='access_reviews')$content.='<section class="card"><h2>Create access review</h2><form method="post"><label>Review name</label><input name="review_name" required maxlength="180"><label>Scope and checklist</label><textarea name="scope_description" required></textarea><label>Due date</label><input type="date" name="due_date"><p><button class="btn primary">Create review</button></p></form></section>';
if($key==='retention')$content.='<section class="card"><h2>Add retention review</h2><p class="muted">No records are automatically deleted by this module. Check legal holds and approvals before any disposition.</p><form method="post"><div class="grid"><div><label>Record category</label><input name="record_category" required maxlength="150"></div><div><label>Retention period</label><input name="retention_period" required maxlength="100"></div></div><label>Retention basis / policy reference</label><input name="retention_basis" required maxlength="255"><label>Due date</label><input type="date" name="due_date"><p><button class="btn primary">Add review</button></p></form></section>';
if($key==='consents'){$title='Consent oversight';$desc='Read-only monitoring of consent status; candidates control their own consent.';$content='<section class="card"><p class="note">This module is read-only. Do not grant or revoke consent on behalf of a candidate. A consent record alone does not determine every lawful processing purpose.</p>';if(!ioHas($db,'candidate_consents'))$content.='<p>candidate_consents table is unavailable.</p>';else{$r=$db->query('SELECT consent_type,status,COUNT(*) records,MAX(created_at) latest_record FROM candidate_consents GROUP BY consent_type,status ORDER BY consent_type,status');$content.='<div class="scroll"><table><tr><th>Consent type</th><th>Status</th><th>Records</th><th>Latest record</th></tr>';while($a=$r->fetch_assoc())$content.='<tr><td>'.ioe($a['consent_type']).'</td><td>'.ioe($a['status']).'</td><td>'.(int)$a['records'].'</td><td>'.ioe($a['latest_record']).'</td></tr>';$content.='</table></div>';}$content.='</section>';}

if($key==='processing')$content.='<section class="card"><h2>Register processing activity</h2><p class="muted">Record purpose, information categories, affected people, lawful basis and safeguards. Select the applicable POPIA justification only after confirming it with the organisation’s approved legal/policy guidance.</p><form method="post"><div class="grid"><div><label>Activity name</label><input name="activity_name" required maxlength="180"></div><div><label>Business owner / responsible team</label><input name="business_owner" required maxlength="180"></div><div><label>Personal information categories</label><input name="personal_information_categories" required placeholder="e.g. contact, identity, education"></div><div><label>Data subject categories</label><input name="data_subject_categories" required placeholder="e.g. candidates, employees"></div><div><label>Lawful basis / POPIA justification</label><select name="lawful_basis" required><option value="">Select and verify</option><option>consent</option><option>contract</option><option>legal_obligation</option><option>legitimate_interest</option><option>public_law_duty</option><option>other_popia_ground</option></select></div><div><label>Recipients / access groups</label><input name="recipients" maxlength="1000"></div><div><label>Cross-border transfer?</label><select name="cross_border_transfer"><option value="no">No / not identified</option><option value="yes">Yes / requires assessment</option></select></div><div><label>Next review date</label><input type="date" name="review_due_date"></div></div><label>Processing purpose</label><textarea name="purpose" required maxlength="5000"></textarea><label>Security safeguards</label><textarea name="security_safeguards" required maxlength="5000"></textarea><p><button class="btn primary">Save processing activity</button></p></form></section>';
if($key==='operators')$content.='<section class="card"><h2>Register operator</h2><form method="post"><div class="grid"><div><label>Operator / service provider</label><input name="operator_name" required maxlength="180"></div><div><label>Agreement reference</label><input name="agreement_reference" maxlength="180"></div><div><label>Information categories handled</label><input name="information_categories" maxlength="1000"></div><div><label>Incident contact</label><input name="incident_contact" maxlength="255"></div><div><label>Next review date</label><input type="date" name="review_due_date"></div></div><label>Service description</label><textarea name="service_description" required maxlength="4000"></textarea><label>Security measures / written safeguards</label><textarea name="security_measures" required maxlength="5000"></textarea><p><button class="btn primary">Save operator</button></p></form></section>';

if($key==='reports'){$title='Privacy reports';$desc='Live operational indicators from installed workflow tables.';$content='<section class="card"><h2>Privacy operations summary</h2><div class="scroll"><table><tr><th>Metric</th><th>Value</th></tr>';foreach([['Open requests','io_data_subject_requests',"status NOT IN ('completed','rejected','closed')"],['Open incidents','io_privacy_incidents',"status NOT IN ('closed','resolved')"],['Retention reviews due','io_retention_reviews',"status IN ('pending','review') AND due_date<=CURDATE()"],['Access reviews pending','io_access_reviews',"status IN ('pending','in_progress')"]] as $m){$val='Not installed';if(ioHas($db,$m[1])){$r=$db->query('SELECT COUNT(*) n FROM '.$m[1].' WHERE '.$m[2]);$val=(string)(int)$r->fetch_assoc()['n'];}$content.='<tr><td>'.ioe($m[0]).'</td><td>'.ioe($val).'</td></tr>';}$content.='</table></div><p><button class="btn" onclick="window.print()">Print / Save PDF</button></p></section>';}
if($key==='settings'){$title='Governance settings';$desc='Review operational controls and configuration decisions.';$content='<section class="card"><h2>Governance checklist</h2><ul><li>Set response targets according to approved policy.</li><li>Assign an incident escalation owner.</li><li>Record approved retention schedules and legal-hold procedures.</li><li>Schedule periodic privileged-access reviews.</li><li>Use MFA, least privilege and protected audit logs.</li></ul><p class="muted">Settings are guidance-only and are not persisted. Configure policy values only after organisational approval.</p></section>';}
if($key!=='consents'&&$key!=='reports'&&$key!=='settings'){$content.='<section class="card"><h2>Register</h2>';if(!ioHas($db,$table))$content.='<p class="note">Workflow table not installed. Run database/information_officer_portal.sql.</p>';else{$r=$db->query('SELECT '.implode(',',array_map(fn($x)=>'`'.$x.'`',$cols)).' FROM `'.$table.'` ORDER BY `'.($key==='audit'?'created_at':'id').'` DESC LIMIT 100');$content.='<div class="scroll"><table><tr>';foreach($cols as $x)$content.='<th>'.ioe(str_replace('_',' ',$x)).'</th>';$content.='</tr>';if(!$r->num_rows)$content.='<tr><td colspan="'.count($cols).'">No records yet.</td></tr>';while($a=$r->fetch_assoc()){$content.='<tr>';foreach($cols as $x)$content.='<td>'.ioe($a[$x]??'').'</td>';$content.='</tr>';}$content.='</table></div>';}$content.='</section>';}
if($message!=='')$content='<div class="note">'.ioe($message).'</div>'.$content;
?><!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=ioe($title)?> | Information Officer</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet"><style>:root{--bg:#f5f7fb;--card:#fff;--tx:#172235;--mut:#687385;--line:#e2e8f0;--ac:#2458d3}html[data-theme=dark]{--bg:#101722;--card:#182332;--tx:#edf2f8;--mut:#a7b3c4;--line:#2c394a;--ac:#8eb3ff;color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:14px Inter,Arial}.wrap{max-width:1250px;margin:auto;padding:25px 18px}header{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap}h1{margin:0 0 6px;font-size:30px}.muted{color:var(--mut);line-height:1.6}.nav{display:flex;gap:7px;flex-wrap:wrap;margin:20px 0}.profile-chip{display:inline-flex;align-items:center;gap:8px;padding:5px 10px 5px 5px;border:1px solid var(--line);border-radius:999px;background:var(--card);color:var(--tx);font-size:12px;font-weight:700}.profile-avatar{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--bg);color:var(--ac);font-size:11px;font-weight:800}.btn.logout{background:#b42318;color:#fff;border-color:#b42318}.btn.logout:hover{background:#912018}.btn:focus-visible,a:focus-visible{outline:3px solid var(--ac);outline-offset:2px}.nav a,.btn{padding:9px 12px;border:1px solid var(--line);border-radius:9px;color:var(--tx);background:var(--card);text-decoration:none;cursor:pointer;font:600 12px Inter}.primary{background:var(--ac);color:white}.card{background:var(--card);border:1px solid var(--line);border-radius:15px;padding:18px;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}label{display:block;font-size:12px;font-weight:700;margin:10px 0 5px}input,select,textarea{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--tx);font:14px Inter}textarea{min-height:90px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}td,th{padding:10px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--mut);text-transform:uppercase;font-size:10px}.note{background:#eaf1ff;color:#172235;padding:12px;border-radius:9px;line-height:1.5}@media(max-width:600px){.grid{grid-template-columns:1fr}.wrap{padding:16px 12px}}</style></head><body><main class="wrap"><header><div><h1><?=ioe($title)?></h1><div class="muted"><?=ioe($desc)?></div></div><div><a class="btn" href="<?=ioe(url('privacy/dashboard.php'))?>">Dashboard</a> <button class="btn" id="theme">Theme</button></div></header><nav class="nav"><?php foreach(['requests'=>'Requests','incidents'=>'Incidents','consents'=>'Consent','access_reviews'=>'Access reviews','retention'=>'Retention','audit'=>'Audit log','processing'=>'Processing inventory','operators'=>'Operators','breach_management'=>'Incident & breach management','reports'=>'Reports','settings'=>'Settings'] as $k=>$v):?><a href="<?=ioe(url('privacy/'.$k.'.php'))?>"><?=ioe($v)?></a><?php endforeach;?></nav><?= $content ?></main><script>let r=document.documentElement;if(localStorage.getItem('io-theme')==='dark')r.dataset.theme='dark';document.getElementById('theme').onclick=()=>{r.dataset.theme=r.dataset.theme==='dark'?'light':'dark';localStorage.setItem('io-theme',r.dataset.theme)}</script></body></html>
